begin;
select plan(28);
insert into auth.users(id) values ('55000000-0000-4000-8000-000000000001');
insert into auth.sessions(id,user_id) values ('65000000-0000-4000-8000-000000000001','55000000-0000-4000-8000-000000000001');
insert into public.staff_members(user_id,active) values ('55000000-0000-4000-8000-000000000001',true);
select set_config('request.jwt.claims','{"sub":"55000000-0000-4000-8000-000000000001","session_id":"65000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
create temporary table profile_test(value jsonb);
grant all on profile_test to authenticated;
set local role authenticated;
insert into profile_test select public.save_animal(repeat('P',32),' {"name":"Perfil público","species":"dog","sex":"female","size":"small","approximate_age":"2 anos","clinical_notes":"Segredo clínico","last_dewormed_on":"2024-02-29","temperament":" Calmo e sociável "}');
select is((select value->'animal'->>'last_dewormed_on' from profile_test),'2024-02-29','valid leap date remains civil');
select is((select value->'animal'->>'temperament' from profile_test),'Calmo e sociável','public summary trimmed');
select is((select value->'animal'->>'is_published' from profile_test),'false','new profile remains private');
select is(public.save_animal(repeat('P',32),'{"name":"Perfil público","species":"dog","sex":"female","size":"small","approximate_age":"2 anos","clinical_notes":"Segredo clínico","last_dewormed_on":"2024-02-29","temperament":"Calmo e sociável"}'),(select value from profile_test),'normalized replay retains original confirmation');
select throws_ok($$select public.save_animal(repeat('P',32),'{"name":"Perfil público","species":"dog","sex":"female","size":"small","approximate_age":"2 anos","clinical_notes":"Segredo clínico","last_dewormed_on":"2024-02-29","temperament":"Outro"}')$$,'PT409','operation_conflict','changed profile with same key conflicts');
select public.save_animal(repeat('Q',32),jsonb_build_object('id',(select value->'animal'->>'id' from profile_test),'name','Perfil público','species','dog','sex','female','size','small','approximate_age','2 anos','clinical_notes','Segredo clínico'));
select is(public.get_managed_animal((select (value->'animal'->>'id')::uuid from profile_test))->'animal'->>'last_dewormed_on','2024-02-29','legacy omitted date preserves current value');
select is(public.get_managed_animal((select (value->'animal'->>'id')::uuid from profile_test))->'animal'->>'temperament','Calmo e sociável','legacy omitted temperament preserves current value');
select public.save_animal(repeat('R',32),jsonb_build_object('id',(select value->'animal'->>'id' from profile_test),'name','Perfil público','species','dog','sex','female','size','small','approximate_age','2 anos','clinical_notes','Segredo clínico','last_dewormed_on',null,'temperament',' '));
select is(public.get_managed_animal((select (value->'animal'->>'id')::uuid from profile_test))->'animal'->>'last_dewormed_on',null::text,'explicit null clears date');
select is(public.get_managed_animal((select (value->'animal'->>'id')::uuid from profile_test))->'animal'->>'temperament',null::text,'blank clears temperament');
select throws_ok($$select public.save_animal(repeat('S',32),'{"name":"Inválido","species":"dog","sex":"female","size":"small","approximate_age":"2","last_dewormed_on":"2026-02-31"}')$$,'22023','invalid_payload','invalid calendar rejected');
select throws_ok(format('select public.save_animal(%L,%L::jsonb)',repeat('T',32),jsonb_build_object('name','Futuro','species','dog','sex','female','size','small','approximate_age','2','last_dewormed_on',((current_timestamp at time zone 'America/Sao_Paulo')::date+1)::text)),'22023','invalid_payload','future application rejected in shelter timezone');
select throws_ok(format('select public.save_animal(%L,%L::jsonb)',repeat('U',32),jsonb_build_object('name','Longo','species','dog','sex','female','size','small','approximate_age','2','temperament',repeat('x',121))),'22023','invalid_payload','121 code points rejected');
select lives_ok(format('select public.save_animal(%L,%L::jsonb)',repeat('V',32),jsonb_build_object('name','Hoje','species','dog','sex','female','size','small','approximate_age','2','last_dewormed_on',((current_timestamp at time zone 'America/Sao_Paulo')::date)::text,'temperament',repeat('ç',120))),'today and exactly 120 code points accepted');
select lives_ok($$select public.save_animal(repeat('Y',32),'{"name":"Características","species":"cat","sex":"male","size":"small","approximate_age":"1","weight_kg":4.25,"color":" Branco ","vaccinations":[{"applied_on":"2024-02-29","vaccine_type":" V4 "}]}')$$,'public characteristics accepted');
select is((select color from public.animals where name='Características'),'Branco','color normalized');
select is((select weight_kg from public.animals where name='Características'),4.25::numeric,'weight preserved');
select is((select vaccinations from public.animals where name='Características'),'[{"applied_on":"2024-02-29","vaccine_type":"V4"}]'::jsonb,'vaccinations contain only date and type');
select throws_ok($$select public.save_animal(repeat('Z',32),'{"name":"Inválido","species":"cat","sex":"male","size":"small","approximate_age":"1","weight_kg":0}')$$,'22023','invalid_payload','zero weight rejected');
select throws_ok($$select public.save_animal(repeat('a',32),'{"name":"Inválido","species":"cat","sex":"male","size":"small","approximate_age":"1","vaccinations":[{"applied_on":"2024-02-31","vaccine_type":"V4"}]}')$$,'22023','invalid_payload','invalid vaccination date rejected');
select throws_ok($$select public.save_animal(repeat('b',32),'{"name":"Inválido","species":"cat","sex":"male","size":"small","approximate_age":"1","vaccinations":[{"applied_on":"2024-02-29","vaccine_type":"V4","notes":"private"}]}')$$,'22023','invalid_payload','private vaccination attributes rejected');
select lives_ok(format('select public.save_animal(%L,%L::jsonb)',repeat('c',32),jsonb_build_object('id',(select id from public.animals where name='Características'),'name','Características','species','cat','sex','male','size','small','approximate_age','1')),'legacy client can edit');
select is((select weight_kg from public.animals where name='Características'),4.25::numeric,'legacy omission preserves weight');
select lives_ok(format('select public.save_animal(%L,%L::jsonb)',repeat('d',32),jsonb_build_object('id',(select id from public.animals where name='Características'),'name','Características','species','cat','sex','male','size','small','approximate_age','1','weight_kg',null,'color',null,'vaccinations','[]'::jsonb)),'explicit clearing accepted');
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select is((select count(*)::int from public.animals where name='Perfil público'),0,'private profile invisible');
select throws_ok($$select public.save_animal(repeat('W',32),'{}')$$,'42501',null,'anonymous writes denied');
reset role;
update public.animals set is_published=true where name='Perfil público';
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select is((select count(*)::int from public.animals where name='Perfil público'),1,'published public profile readable');
reset role;
update public.animals set status='adopted' where name='Perfil público';
select set_config('request.jwt.claims','{"role":"anon"}',true);
set local role anon;
select is((select count(*)::int from public.animals where name='Perfil público'),0,'adopted public profile hidden');
reset role;
update public.staff_members set active=false where user_id='55000000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims','{"sub":"55000000-0000-4000-8000-000000000001","session_id":"65000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select throws_ok($$select public.save_animal(repeat('X',32),'{}')$$,'42501','staff_required','membership revoked before profile write');
select * from finish();
rollback;
